/**
 * RepairGraph.ts — Logical Recovery Plan Structure
 *
 * Represents an automated, platform-independent recovery workflow generated by the RepairPlanner.
 * Contains purely logical Action nodes (NEVER raw shell commands or AppleScript snippets).
 * Executed deterministically through the existing Phase 4 Runtime and Phase 5 Capability SDK bridge.
 */

import { RepairGraph, RepairNode } from '../models/RepairTypes';
import { FailureDiagnosis } from '../models/FailureClassification';

export class RepairGraphBuilder {
  private id: string;
  private targetActionId: string;
  private diagnosis: FailureDiagnosis;
  private nodes: RepairNode[] = [];
  private strategyName: string;

  constructor(targetActionId: string, diagnosis: FailureDiagnosis, strategyName: string) {
    this.id = `repair-graph-${Date.now()}-${Math.random().toString(36).substring(2, 6)}`;
    this.targetActionId = targetActionId;
    this.diagnosis = diagnosis;
    this.strategyName = strategyName;
  }

  /**
   * Add a strongly-typed logical recovery action node to the repair workflow graph.
   * Never pass shell commands; always refer to formal Action Registry IDs.
   */
  public addLogicalAction(
    actionId: string,
    description: string,
    parameters: Record<string, unknown> = {},
    dependencies: string[] = []
  ): string {
    const nodeId = `rn-${this.nodes.length + 1}-${actionId}`;
    const node: RepairNode = {
      id: nodeId,
      actionId,
      parameters,
      description,
      dependencies,
    };
    this.nodes.push(node);
    return nodeId;
  }

  public build(): RepairGraph {
    if (this.nodes.length === 0) {
      throw new Error(`Cannot build empty RepairGraph for target action [${this.targetActionId}]`);
    }

    return {
      id: this.id,
      targetActionId: this.targetActionId,
      diagnosis: this.diagnosis,
      nodes: [...this.nodes],
      strategyName: this.strategyName,
      createdTimestamp: Date.now(),
    };
  }

  public static generateExampleBluetoothRecovery(diagnosis: FailureDiagnosis): RepairGraph {
    const builder = new RepairGraphBuilder('bluetooth.connect', diagnosis, 'StateRefresh & Retry');
    
    const enableRadio = builder.addLogicalAction('network.bluetooth.on', 'Enable Bluetooth hardware radio power');
    const verifyRadio = builder.addLogicalAction('system.verify.state', 'Verify radio powered status via State Engine', { domain: 'bluetooth', property: 'powered', expected: true }, [enableRadio]);
    const reconnect = builder.addLogicalAction('network.bluetooth.connect', 'Reconnect peripheral device via blueutil driver', { device: 'Magic Keyboard' }, [verifyRadio]);
    builder.addLogicalAction('system.verify.state', 'Verify connection status across multi-stage verifier', { domain: 'bluetooth', property: 'isConnected', target: 'Magic Keyboard' }, [reconnect]);

    return builder.build();
  }
}
